	accession_no NVARCHAR(25) NULL, 
	section_code NVARCHAR(20) NULL, 
	snippet NVARCHAR(2000) NULL, 
	method NVARCHAR(10) NOT NULL DEFAULT 'RULE', 
	review_status NVARCHAR(12) NOT NULL DEFAULT 'RULE_ONLY', 
	votes_json NVARCHAR(500) NULL, 
	detected_at DATETIMEOFFSET NOT NULL, 
	PRIMARY KEY (signal_id), 
	UNIQUE (signal_key), 
	FOREIGN KEY(company_id) REFERENCES uw_pipeline.company (company_id), 
	FOREIGN KEY(doc_id) REFERENCES uw_pipeline.source_document (doc_id)
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_signal_company_id' AND object_id = OBJECT_ID(N'uw_pipeline.signal'))
    CREATE INDEX ix_signal_company_id ON uw_pipeline.signal (company_id);
GO

IF OBJECT_ID(N'uw_pipeline.signal_vote', N'U') IS NULL
CREATE TABLE uw_pipeline.signal_vote (
	vote_id INTEGER NOT NULL IDENTITY, 
	company_id INTEGER NOT NULL, 
	doc_id INTEGER NOT NULL, 
	topic NVARCHAR(40) NOT NULL, 
	rule_value NVARCHAR(30) NOT NULL, 
	extractor_value NVARCHAR(30) NULL, 
	tiebreak_value NVARCHAR(30) NULL, 
	outcome NVARCHAR(30) NOT NULL, 
	status NVARCHAR(12) NOT NULL, 
	evidence NVARCHAR(2000) NULL, 
	updated_at DATETIMEOFFSET NOT NULL, 
	PRIMARY KEY (vote_id), 
	CONSTRAINT uq_signal_vote UNIQUE (doc_id, topic), 
	FOREIGN KEY(company_id) REFERENCES uw_pipeline.company (company_id), 
	FOREIGN KEY(doc_id) REFERENCES uw_pipeline.source_document (doc_id)
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_signal_vote_company_id' AND object_id = OBJECT_ID(N'uw_pipeline.signal_vote'))
    CREATE INDEX ix_signal_vote_company_id ON uw_pipeline.signal_vote (company_id);
GO

IF OBJECT_ID(N'uw_pipeline.transcript_flag', N'U') IS NULL
CREATE TABLE uw_pipeline.transcript_flag (
	doc_id INTEGER NOT NULL, 
	flag_index INTEGER NOT NULL, 
	category NVARCHAR(30) NOT NULL, 
	flag_text NVARCHAR(1000) NOT NULL, 
	chunk_index INTEGER NOT NULL, 
	PRIMARY KEY (doc_id, flag_index), 
	FOREIGN KEY(doc_id) REFERENCES uw_pipeline.source_document (doc_id)
);
GO

IF OBJECT_ID(N'uw_pipeline.transcript_tone', N'U') IS NULL
CREATE TABLE uw_pipeline.transcript_tone (
	doc_id INTEGER NOT NULL, 
	company_id INTEGER NOT NULL, 
	overall_tone FLOAT NULL, 
	confidence FLOAT NULL, 
	hedging FLOAT NULL, 
	uncertainty FLOAT NULL, 
	forward_looking FLOAT NULL, 
	liability_cues FLOAT NULL, 
	n_chunks INTEGER NOT NULL, 
	n_chunks_attempted INTEGER NOT NULL, 
	model NVARCHAR(60) NOT NULL, 
	prompt_version NVARCHAR(40) NOT NULL, 
	input_hash NVARCHAR(64) NOT NULL, 
	run_id INTEGER NULL, 
	created_at DATETIMEOFFSET NOT NULL, 
	PRIMARY KEY (doc_id), 
	FOREIGN KEY(doc_id) REFERENCES uw_pipeline.source_document (doc_id), 
	FOREIGN KEY(company_id) REFERENCES uw_pipeline.company (company_id)
);
GO

IF OBJECT_ID(N'uw_pipeline.section_chunk', N'U') IS NULL
CREATE TABLE uw_pipeline.section_chunk (
	chunk_id INTEGER NOT NULL IDENTITY, 
	section_id INTEGER NOT NULL, 
	chunk_index INTEGER NOT NULL, 
	start_offset INTEGER NOT NULL, 
	end_offset INTEGER NOT NULL, 
	text NVARCHAR(max) NOT NULL, 
	PRIMARY KEY (chunk_id), 
	CONSTRAINT uq_section_chunk UNIQUE (section_id, chunk_index), 
	FOREIGN KEY(section_id) REFERENCES uw_pipeline.filing_section (section_id)
);
GO
